import{_ as i,o as n,c as a,a0 as t}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /grill-integration-spec","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/grill-integration-spec.md","filePath":"references/skills/grill-integration-spec.md"}'),o={name:"references/skills/grill-integration-spec.md"};function c(l,e,r,d,h,s){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="skill-grill-integration-spec" tabindex="-1">Skill: <code>/grill-integration-spec</code> <a class="header-anchor" href="#skill-grill-integration-spec" aria-label="Permalink to &quot;Skill: `/grill-integration-spec`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>grill-integration-spec</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/grill-integration-spec &lt;provider/slug&gt;</code></li><li>Chạy SAU KHI <code>/api-integration</code> đã hoàn tất, và TRƯỚC KHI chuyển sang hệ thống sinh code Backend.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc file hợp đồng Backend Integration tại <code>surfaces/integrations/&lt;provider&gt;/&lt;slug&gt;/api/&lt;seq&gt;/01-backend-spec.yaml</code>.</li><li>Tuyệt đối KHÔNG đọc <code>ir/design.yaml</code> vì Integration API hiếm khi có giao diện Frontend đi kèm.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>File <code>01-backend-spec.yaml</code> được vá/bổ sung nếu thiếu sót về Auth, Idempotency, Retry logic.</li><li>Bổ sung các thẻ gencode (<code>codegen.profile</code>, <code>entity</code>, <code>module</code>, <code>#gen:*</code>, <code>#manual-service</code>).</li><li>Cập nhật trạng thái <code>approval.status</code> thành <code>reviewed</code> (hoặc <code>approved</code>).</li><li>Chạy qua các cổng kiểm định CLI: <code>flowgrid openapi_gen</code> và <code>flowgrid openapi_render</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Đóng vai trò là &quot;Kiểm toán viên&quot; (Auditor) dành riêng cho các hợp đồng giao tiếp ngoại vi (Webhook, Partner API).</li><li>Đảm bảo rằng hợp đồng kết nối với đối tác (Provider) đã có đủ các lớp bảo mật (Auth/SecuritySchemes) và các cơ chế kỹ thuật phức tạp (như chống trùng lặp dữ liệu - Idempotency, tự động thử lại - Retry).</li><li>Khác với API của ứng dụng nội bộ, API tích hợp không chịu sự chi phối của cấu trúc màn hình, do đó Agent chỉ tập trung đối chiếu với tài liệu của đối tác.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Nhận dữ liệu thô từ <code>/api-integration</code>.</li><li><strong>Sau đó:</strong> Nếu được đánh dấu <code>approved</code>, có thể bàn giao cho hệ thống bộ code BE (<code>/api</code> với cờ <code>--type=be</code>) để sinh code.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Cấm đoán:</strong> Không tự ý viết mã nguồn Backend, không sinh các bản báo cáo Markdown rườm rà.</li><li>KHÔNG BẮT BUỘC phải đồng bộ mô hình dữ liệu với Frontend (Portal Testcase hay FE model alignment) vì tích hợp bên thứ 3 thường có Data schema độc lập.</li><li>Không bao giờ được đánh dấu &quot;Ready for code&quot; (sẵn sàng sinh code) nếu chưa có bằng chứng đã chạy vượt qua các lệnh kiểm định bộ docs (<code>flowgrid check</code>, <code>flowgrid openapi_gen</code>, …).</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/grill-integration-spec</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const p=i(o,[["render",c]]);export{u as __pageData,p as default};
